-- Source: japan_seichi_research_2026-09-25.csv (233 rows)
on conflict ("レコードID") do nothing;

-- Run after importing the CSV into public.seichi_research_import.
select
  "作品ID",
  min("作品名"),
  min("分類"),
  min("作品版"),
  array_agg(distinct concat_ws('・', nullif("都道府県", ''), nullif("市区町村等", ''))
    order by concat_ws('・', nullif("都道府県", ''), nullif("市区町村等", ''))),
  count(*)::integer,
  min("作品名") || ' ' || string_agg(distinct concat_ws(' ', "都道府県", "市区町村等"), ' ')
from public.seichi_research_import
group by "作品ID"
on conflict (id) do update set
  title = excluded.title,
  category = excluded.category,
  version = excluded.version,
  regions = excluded.regions,
  spot_count = excluded.spot_count,
  search_text = excluded.search_text;

-- AniList mappings are reviewed separately from the research CSV.
update public.research_works as work
set anilist_id = matches.anilist_id
from (values
  ('w_bdee7837dcb857', 101610),
  ('w_b620bd6dfb2b3f', 1029),
  ('w_19a5085e2bf441', 1689),
  ('w_b0b4f44d5a0d4e', 99426),
  ('w_57c71c259d1a53', 1887),
  ('w_e1a48272cf20fe', 585),
  ('w_6bc11183b70829', 12355),
  ('w_395a92281c2f9a', 9289),
  ('w_2332ba4a9956a9', 98444),
  ('w_260ac5bdef91d7', 5681),
  ('w_34615c1734a950', 12189),
  ('w_acbf524039d3e2', 21519),
  ('w_f52cc2944adca3', 104459),
  ('w_f195b04b0427da', 171457),
  ('w_fb41b868e0f278', 5680),
  ('w_5e5c5d8896363f', 183384),
  ('w_ddeeef2d11934b', 129201),
  ('w_fca3c0ec7c5c9e', 115113),
  ('w_187519a9729659', 21158),
  ('w_549e5dcc5507e8', 5084),
  ('w_3b3cdaf9bff7ce', 127271),
  ('w_cde70fdf82d150', 21709),
  ('w_6305e34a073c04', 101316)
) as matches(work_id, anilist_id)
where work.id = matches.work_id;

-- Pilot: the city's official "Your Name" route names both places and states
-- library -> station is a seven-minute walk. Coordinates are OSM feature centers,
-- not exact photo viewpoints; verify entrances on the day of travel.
   coordinate_source_url, visit_confirmed_at, access_note, stay_minutes,
   closed_weekdays, closed_last_friday, notes)
values
  ('p_62fa22236aff1e', 'w_acbf524039d3e2', '飛騨市図書館', '岐阜県・飛騨市',
   36.2381173, 137.1854688, 'https://www.hida-kankou.jp/courses/73',
   'https://www.openstreetmap.org/way/479056924', now(),
   '通常は火～土・祝日9:00～20:00、日曜9:00～17:00。月曜（祝日の場合は翌平日）・最終金曜・年末年始・特別点検は休館。訪問前に図書館公式サイトで当日の開館を確認してください。',
   20, array[1]::smallint[], true,
   '開館・休館条件: https://hida-lib.jp/toshow/html/access.html。祝日の月曜と翌平日、臨時休館は自動判定できません。'),
  ('p_ac7db5247c45a6', 'w_acbf524039d3e2', '飛騨古川駅', '岐阜県・飛騨市',
   36.2367306, 137.1896089, 'https://www.hida-kankou.jp/courses/73',
   'https://www.openstreetmap.org/way/478848236', now(),
   '駅前・駅舎周辺を見学。ホーム等の改札内へは有効な乗車券が必要です。運行・立入条件は現地で確認してください。',
   15, '{}'::smallint[], false,
   '座標は駅舎の中心付近で、作品と同じ撮影視点ではありません。')
on conflict (id) do update set
  work_id = excluded.work_id, name = excluded.name, region = excluded.region,
  latitude = excluded.latitude, longitude = excluded.longitude,
  source_url = excluded.source_url, coordinate_source_url = excluded.coordinate_source_url,
  access_note = excluded.access_note, stay_minutes = excluded.stay_minutes,
  closed_weekdays = excluded.closed_weekdays,
  closed_last_friday = excluded.closed_last_friday, notes = excluded.notes;

   'https://www.hida-kankou.jp/courses/73', now())
on conflict (from_spot_id, to_spot_id) do update set
  mode = excluded.mode, minutes = excluded.minutes, source_url = excluded.source_url;
